1	import java.util.*;
2	import java.util.stream.Collectors;
3	
4	/**
5	 * A class representing shared characteristics of animals.
6	 *
7	 * @version 2022.03.02
8	 */
9	public abstract class Animal extends Organism implements Actor
10	{
11	    protected int age;
12	    protected int foodLevel;
13	    protected Gender sex;
14	
15	    protected static final Random rand = Randomizer.getRandom();
16	
17	    // An animal's chance of contracting a disease at birth
18	    private static final double RANDOM_CONTRACTION_RATE = 0.002;
19	
20	    /**
21	     * Returns this species' immutable configuration constants.
22	     * Each concrete subclass provides a static AnimalStats instance.
23	     */
24	    protected abstract AnimalStats getStats();
25	
26	    @Override
27	    protected int FOOD_VALUE() { return getStats().getFoodValue(); }
28	
29	    /**
30	     * Create a new animal at location in field.
31	     *
32	     * @param field The field currently occupied.
33	     * @param location The location within the field.
34	     * @param randomAge If true, start with a random age and food level.
35	     * @param sex The animal's gender.
36	     */
37	    public Animal(Field field, Location location, boolean randomAge, Gender sex)
38	    {
39	        super(field, location);
40	        this.sex = sex;
41	        if (randomAge) {
42	            this.age = rand.nextInt(getStats().getMaxAge());
43	            foodLevel = rand.nextInt(getStats().getMaxFoodLevel());
44	        } else {
45	            this.age = 0;
46	            foodLevel = getStats().getMaxFoodLevel();
47	        }
48	        randomlyContractDisease();
49	    }
50	
51	    /**
52	     * Make this animal act - that is: make it do whatever it wants/needs to do.
53	     * @param newAnimals A list to receive newly born animals.
54	     * @param environment The environment that the animal resides in.
55	     */
56	    public void act(List<Actor> newAnimals, Environment environment)
57	    {
58	        if (!isAwake(environment)) {
59	            return;
60	        }
61	        if (isDiseased() && getDisease().getPropagationRate() <= rand.nextDouble()) {
62	            setDead();
63	            return;
64	        }
65	        randomlyContractDisease();
66	        incrementAge();
67	        incrementHunger();
68	        if (isAlive()) {
69	            giveBirth(newAnimals, environment);
70	            Location newLocation = findFood();
71	            if (newLocation == null) {
72	                newLocation = getField().freeAdjacentLocation(getLocation());
73	            }
74	
75	            List<Location> adjacentGrassSpots = getField().adjacentLocationsWithSpecies(getLocation(), Grass.class);
76	
77	            if (newLocation != null) {
78	                setLocation(newLocation);
79	            } else if (adjacentGrassSpots.size() > 0) {
80	                getField().clear(getLocation());
81	                setLocation(adjacentGrassSpots.get(rand.nextInt(adjacentGrassSpots.size())));
82	            } else {
83	                // Overcrowding
84	                setDead();
85	            }
86	
87	            if (isDiseased() && getDisease().getLethalityRate() <= rand.nextDouble()) {
88	                setDead();
89	            }
90	        }
91	    }
92	
93	    /**
94	     * Look for food adjacent to the current location.
95	     * Only the first food item is eaten.
96	     * @return Where food was found, or null if it wasn't.
97	     */
98	    protected Location findFood()
99	    {
100	        Field field = getField();
101	        List<Location> adjacent = field.adjacentLocations(getLocation());
102	
103	        scanForContactDisease(adjacent);
104	
105	        for (Location where : adjacent) {
106	            Object obj = field.getObjectAt(where);
107	            if (obj != null && getStats().getDiet().contains(obj.getClass())) {
108	                Organism food = (Organism) obj;
109	                tryContractFoodbornDisease(food);
110	                if (food.isAlive()) {
111	                    food.setDead();
112	                    foodLevel = Math.min(foodLevel + food.FOOD_VALUE(), getStats().getMaxFoodLevel());
113	                    return where;
114	                }
115	                return where;
116	            }
117	        }
118	        return null;
119	    }
120	
121	    // --- Disease transmission helpers ---
122	
123	    /** Scans adjacent locations for non-contact diseases and contracts the first one found. */
124	    private void scanForContactDisease(List<Location> adjacent)
125	    {
126	        Field field = getField();
127	        for (Location loc : adjacent) {
128	            Object obj = field.getObjectAt(loc);
129	            if (obj instanceof Organism) {
130	                Organism organism = (Organism) obj;
131	                if (organism.isDiseased()
132	                        && organism.getDisease().getDiseaseType() != DiseaseType.CONTACT
133	                        && organism.getDisease().getPropagationRate() <= rand.nextDouble()) {
134	                    setDisease(organism.getDisease());
135	                    break;
136	                }
137	            }
138	        }
139	    }
140	
141	    /** Attempts to contract a foodborne disease from prey being eaten. */
142	    private void tryContractFoodbornDisease(Organism food)
143	    {
144	        if (food.isDiseased()
145	                && food.getDisease().getDiseaseType() == DiseaseType.FOODBORNE
146	                && food.getDisease().getPropagationRate() <= rand.nextDouble()) {
147	            setDisease(food.getDisease());
148	        }
149	    }
150	
151	    /** Attempts to contract a sexually transmitted disease from a breeding mate. */
152	    private void tryContractSexualDisease(Animal mate)
153	    {
154	        if (mate.isDiseased() && mate.getDisease().getDiseaseType() == DiseaseType.SEXUAL) {
155	            setDisease(mate.getDisease());
156	        }
157	    }
158	
159	    // --- Reproduction ---
160	
161	    /**
162	     * Creates a newborn instance of this animal species.
163	     * Each concrete subclass returns its own type.
164	     */
165	    protected abstract Animal createOffspring(Field field, Location location, Gender sex);
166	
167	    /**
168	     * Check whether this animal is to give birth at this step.
169	     * New births will be made into free adjacent locations.
170	     */
171	    protected void giveBirth(List<Actor> newAnimals, Environment environment)
172	    {
173	        Field field = getField();
174	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
175	        int births = breed();
176	        for (int b = 0; b < births && free.size() > 0; b++) {
177	            Location loc = free.remove(0);
178	            Gender offspringSex = Randomizer.getRandomSex();
179	            newAnimals.add(createOffspring(field, loc, offspringSex));
180	        }
181	    }
182	
183	    /**
184	     * Returns the number of births this step, accounting for mate availability
185	     * and disease transmission during mating.
186	     */
187	    protected int breed()
188	    {
189	        int births = 0;
190	        if (canBreed() && rand.nextDouble() <= getStats().getBreedingProbability()) {
191	            births = rand.nextInt(getStats().getMaxLitterSize()) + 1;
192	            List<Organism> mates = getPotentialMates();
193	            Animal mate = (Animal) mates.get(rand.nextInt(mates.size()));
194	            tryContractSexualDisease(mate);
195	        }
196	        return births;
197	    }
198	
199	    /** Returns true if this animal meets the age and mate requirements for breeding. */
200	    protected boolean canBreed()
201	    {
202	        return age >= getStats().getBreedingAge() && getPotentialMates().size() > 0;
203	    }
204	
205	    /** Returns adjacent organisms of the same species and opposite sex. */
206	    protected List<Organism> getPotentialMates()
207	    {
208	        List<Organism> potentialMates = new ArrayList<>();
209	        if (getField() != null) {
210	            potentialMates = getField().adjacentLocations(getLocation()).stream()
211	                    .map(s -> getField().getObjectAt(s))
212	                    .filter(s -> s != null)
213	                    .filter(s -> s.getClass().equals(this.getClass()))
214	                    .filter(s -> this.sex != ((Animal) s).sex)
215	                    .map(s -> (Organism) s)
216	                    .collect(Collectors.toList());
217	        }
218	        return potentialMates;
219	    }
220	
221	    // --- Schedule ---
222	
223	    /** Returns true if the animal is currently awake (respects nocturnal/diurnal schedule). */
224	    public boolean isAwake(Environment environment)
225	    {
226	        if (getStats().isNocturnal()) {
227	            return !environment.getTime().isDay();
228	        }
229	        return environment.getTime().isDay();
230	    }
231	
232	    // --- Lifecycle ---
233	
234	    protected void randomlyContractDisease()
235	    {
236	        if (rand.nextDouble() <= RANDOM_CONTRACTION_RATE) {
237	            setDisease(new Disease());
238	        }
239	    }
240	
241	    /** Increases age; kills the animal if it exceeds its maximum. */
242	    protected void incrementAge()
243	    {
244	        age++;
245	        if (age > getStats().getMaxAge()) {
246	            setDead();
247	        }
248	    }
249	
250	    /** Decreases food level; kills the animal if it reaches zero. */
251	    protected void incrementHunger()
252	    {
253	        foodLevel--;
254	        if (foodLevel <= 0) {
255	            setDead();
256	        }
257	    }
258	}
259

1	import java.util.Set;
2	
3	/**
4	 * Immutable configuration bundle for an animal species.
5	 * Centralises all species-specific constants so that each subclass only needs
6	 * to provide a single static STATS instance rather than implementing abstract
7	 * getter methods or setting protected fields in its constructor.
8	 *
9	 * @version 2022.03.02
10	 */
11	public class AnimalStats
12	{
13	    private final double breedingAge;
14	    private final int maxLitterSize;
15	    private final double breedingProbability;
16	    private final int maxAge;
17	    private final int maxFoodLevel;
18	    private final int foodValue;
19	    private final Set<Class> diet;
20	    private final boolean nocturnal;
21	
22	    public AnimalStats(double breedingAge, int maxLitterSize, double breedingProbability,
23	                       int maxAge, int maxFoodLevel, int foodValue, Set<Class> diet,
24	                       boolean nocturnal)
25	    {
26	        this.breedingAge = breedingAge;
27	        this.maxLitterSize = maxLitterSize;
28	        this.breedingProbability = breedingProbability;
29	        this.maxAge = maxAge;
30	        this.maxFoodLevel = maxFoodLevel;
31	        this.foodValue = foodValue;
32	        this.diet = diet;
33	        this.nocturnal = nocturnal;
34	    }
35	
36	    public double    getBreedingAge()        { return breedingAge; }
37	    public int       getMaxLitterSize()       { return maxLitterSize; }
38	    public double    getBreedingProbability() { return breedingProbability; }
39	    public int       getMaxAge()              { return maxAge; }
40	    public int       getMaxFoodLevel()        { return maxFoodLevel; }
41	    public int       getFoodValue()           { return foodValue; }
42	    public Set<Class> getDiet()              { return diet; }
43	    public boolean   isNocturnal()            { return nocturnal; }
44	}
