1	import java.util.Random;
2	
3	/**
4	 * This class models disease in the simulation. 
5	 * It stores details about the disease such as 
6	 * lethality rate, propagation rate and the method of transmission.
7	 *
8	 * @version 2022.03.2
9	*/
10	public class Disease 
11	{
12	    private Random rand = Randomizer.getRandom();
13	    // The propagation rate of the disease
14	    private double PROPAGATION_RATE = 0.0;
15	    // the lethality rate of the disease
16	    private double LETHALITY_RATE = 0.0;
17	    // the transmission route of the disease 
18	    private DiseaseType PROPAGATION_MODE;
19	
20	    /**
21	     * Creates a new disease with random propagation and lethality rates.
22	     * double randomValue = rangeMin + (rangeMax - rangeMin) * r.nextDouble();
23	     * https://stackoverflow.com/questions/3680637/generate-a-random-double-in-a-range
24	     */
25	    public Disease() 
26	    {
27	        PROPAGATION_RATE = 0.6 * rand.nextDouble(); // max prop. rate is 60%
28	        LETHALITY_RATE = 0.4 * rand.nextDouble(); // max lethality rate is 40%
29	        PROPAGATION_MODE = DiseaseType.values()[rand.nextInt(DiseaseType.values().length)];
30	    }
31	    
32	    /**
33	     * Create a new disease with given propagation and lethality rates.
34	     * @param propRate The propagation rate of the disease.
35	     * @param lethalRate The lethality rate of the disease.
36	     * @param propMode The propagation mode of the disease. 
37	     */
38	    public Disease(double propRate, double lethalRate, DiseaseType propMode)
39	    {
40	        PROPAGATION_RATE = propRate;
41	        LETHALITY_RATE = lethalRate;
42	        PROPAGATION_MODE = propMode;
43	    }
44	
45	    /**
46	     * Returns the propagation rate of the disease
47	     */
48	    public double getPropagationRate() 
49	    {
50	        return PROPAGATION_RATE;
51	    }
52	
53	    /**
54	     * Returns the lethality rate of the disease
55	     */
56	    public double getLethalityRate() 
57	    {
58	        return LETHALITY_RATE;
59	    }
60	
61	    /**
62	     * Returns the disease's mode of transmission
63	     */
64	    public DiseaseType getDiseaseType() 
65	    {
66	        return PROPAGATION_MODE;
67	    }
68	}
