3	/**
4	 * A simple model of an eagle.
5	 * Eagles age, move, contract diseases, eat prey, and die.
6	 * Eagles do not hunt in rainy weather and are not killed by overcrowding.
7	 *
8	 * @version 2022.03.02
9	 */
10	public class Eagle extends Animal
11	{
12	    private static final AnimalStats STATS = new AnimalStats(
13	        15,   // breedingAge
14	        2,    // maxLitterSize
15	        0.4,  // breedingProbability
16	        150,  // maxAge
17	        14,   // maxFoodLevel
18	        5,    // foodValue
19	        Set.of(Deer.class, Coyote.class, Mouse.class),
20	        false // diurnal
21	    );
22	
23	    @Override
24	    protected AnimalStats getStats() { return STATS; }
25	
26	    /**
27	     * Create an eagle. An eagle can be created as a new born (age zero and not hungry)
28	     * or with a random age and food level.
29	     * @param randomAge If true, the eagle will have random age and hunger level.
30	     * @param field The field currently occupied.
31	     * @param location The location within the field.
32	     * @param sex The gender of the eagle.
33	     */
34	    public Eagle(boolean randomAge, Field field, Location location, Gender sex)
35	    {
36	        super(field, location, randomAge, sex);
37	    }
38	
39	    @Override
40	    protected Animal createOffspring(Field field, Location location, Gender sex)
41	    {
42	        return new Eagle(false, field, location, sex);
43	    }
44	
45	    /**
46	     * Eagles act like other animals but do not die from overcrowding (they fly above).
47	     */
48	    @Override
49	    public void act(List<Actor> newAnimals, Environment environment)
50	    {
51	        if (!isAwake(environment)) {
52	            return;
53	        }
54	        if (isDiseased() && getDisease().getPropagationRate() <= rand.nextDouble()) {
55	            setDead();
56	            return;
57	        }
58	        randomlyContractDisease();
59	        incrementAge();
60	        incrementHunger();
61	        if (isAlive()) {
62	            giveBirth(newAnimals, environment);
63	            Location newLocation = findFood(environment);
64	            if (newLocation == null) {
65	                newLocation = getField().freeAdjacentLocation(getLocation());
66	            }
67	            List<Location> adjacentGrassSpots = getField().adjacentLocationsWithSpecies(getLocation(), Grass.class);
68	
69	            if (newLocation != null) {
70	                setLocation(newLocation);
71	            } else if (adjacentGrassSpots.size() > 0) {
72	                getField().clear(getLocation());
73	                setLocation(adjacentGrassSpots.get(rand.nextInt(adjacentGrassSpots.size())));
74	            }
75	            // Eagles are not killed by overcrowding — they fly above the ground
76	
77	            if (isDiseased() && getDisease().getLethalityRate() <= rand.nextDouble()) {
78	                setDead();
79	            }
80	        }
81	    }
82	
83	    /**
84	     * Eagles do not hunt in rainy weather.
85	     * @return Where food was found, or null if it wasn't (or if raining).
86	     */
87	    protected Location findFood(Environment environment)
88	    {
89	        if (environment.getWeather().getCurrentWeather() != WeatherType.RAINING) {
90	            return super.findFood();
91	        }
92	        return null;
93	    }
94	}
