1	import java.util.*;
2	
3	/**
4	 * Represent a rectangular grid of field positions.
5	 * Each position is able to store a single animal.
6	 *
7	 * @version 2022.03.02
8	 */
9	public class Field
10	{
11	    // A random number generator for providing random locations.
12	    private static final Random rand = Randomizer.getRandom();
13	
14	    // The depth and width of the field.
15	    private int depth, width;
16	    // Storage for the animals.
17	    private Object[][] field;
18	
19	    private Set<Location> emptyLocs = new HashSet<>();
20	
21	    /**
22	     * Represent a field of the given dimensions.
23	     * @param depth The depth of the field.
24	     * @param width The width of the field.
25	     */
26	    public Field(int depth, int width)
27	    {
28	        this.depth = depth;
29	        this.width = width;
30	        field = new Object[depth][width];
31	    }
32	    
33	    /**
34	     * Empty the field.
35	     */
36	    public void clear()
37	    {
38	        for(int row = 0; row < depth; row++) {
39	            for(int col = 0; col < width; col++) {
40	                field[row][col] = null;
41	            }
42	        }
43	    }
44	    
45	    /**
46	     * Clear the given location.
47	     * @param location The location to clear.
48	     */
49	    public void clear(Location location)
50	    {
51	        field[location.getRow()][location.getCol()] = null;
52	    }
53	    
54	    /**
55	     * Place an animal at the given location.
56	     * If there is already an animal at the location it will
57	     * be lost.
58	     * @param animal The animal to be placed.
59	     * @param row Row coordinate of the location.
60	     * @param col Column coordinate of the location.
61	     */
62	    public void place(Object animal, int row, int col)
63	    {
64	        place(animal, new Location(row, col));
65	    }
66	    
67	    /**
68	     * Place an animal at the given location.
69	     * If there is already an animal at the location it will
70	     * be lost.
71	     * @param animal The animal to be placed.
72	     * @param location Where to place the animal.
73	     */
74	    public void place(Object animal, Location location)
75	    {
76	        field[location.getRow()][location.getCol()] = animal;
77	    }
78	    
79	    /**
80	     * Return the animal at the given location, if any.
81	     * @param location Where in the field.
82	     * @return The animal at the given location, or null if there is none.
83	     */
84	    public Object getObjectAt(Location location)
85	    {
86	        return getObjectAt(location.getRow(), location.getCol());
87	    }
88	    
89	    /**
90	     * Return the animal at the given location, if any.
91	     * @param row The desired row.
92	     * @param col The desired column.
93	     * @return The animal at the given location, or null if there is none.
94	     */
95	    public Object getObjectAt(int row, int col)
96	    {
97	        return field[row][col];
98	    }
99	
100	    /**
101	     * Generate a random location that is adjacent to the
102	     * given location, or is the same location.
103	     * The returned location will be within the valid bounds
104	     * of the field.
105	     * @param location The location from which to generate an adjacency.
106	     * @return A valid location within the grid area.
107	     */
108	    public Location randomAdjacentLocation(Location location)
109	    {
110	        List<Location> adjacent = adjacentLocations(location);
111	        return adjacent.get(0);
112	    }
113	
114	    /**
115	     * Returns a random set of patches from getFreePatches() based on a given rate
116	     * getFreePatches() returns a list of size n, only (n*rate) random locations are returned
117	     * @param rateOfGeneration The rate
118	     */
119	    public List<Location> getRandomFreePatches(double rateOfGeneration)
120	    {
121	        List<Location> patches = getFreePatches();
122	        List<Location> randPatches = new ArrayList<>();
123	        for(int i=0; i<rateOfGeneration* patches.size(); i++)
124	        {
125	            Location selectedPatch = patches.get(rand.nextInt(patches.size()));
126	            randPatches.add(selectedPatch);
127	            for(Location loc : adjacentLocations(selectedPatch)){
128	                // avoids duplicates in the patches
129	                patches.remove(loc);
130	            }
131	        }
132	        return randPatches;
133	    }
134	
135	    /**
136	     * Gets the free patches in the field and returns them.
137	     * A 'patch' is a 3x3 square of locations, the locations in the list are the centers of said squares
138	     * Patches do not overlap, so the adjacent locations of one patch don't have common locations with
139	     * the adjacent locations of any other square
140	     *
141	     * @return The list of free patches in the field.
142	     */
143	    public List<Location> getFreePatches()
144	    {
145	        List<Location> res = new ArrayList<>();
146	        for(int i=0; i<field.length; i++){
147	            for(int j=0; j<field[1].length; j++){
148	                if (field[i][j] == null){
149	                    List<Location> nearby = adjacentLocations(new Location(i, j));
150	                    boolean allNulls = true;
151	                    for(Location loc : nearby){
152	                        if(getObjectAt(loc) != null){
153	                            allNulls = false;
154	                        }
155	                    }
156	                    if(allNulls){
157	                        res.add(new Location(i, j));
158	                    }
159	                }
160	            }
161	        }
162	
163	        return res;
164	    }
165	
166	    /**
167	     * Get a shuffled list of the free adjacent locations.
168	     * @param location Get locations adjacent to this.
169	     * @return A list of free adjacent locations.
170	     */
171	    public List<Location> getFreeAdjacentLocations(Location location)
172	    {
173	        List<Location> free = new LinkedList<>();
174	        List<Location> adjacent = adjacentLocations(location);
175	        for(Location next : adjacent) {
176	            Object objectAtNext = getObjectAt(next);
177	            if(objectAtNext == null) {
178	                free.add(next);
179	            }
180	        }
181	        return free;
182	    }
183	
184	    /**
185	     * Try to find a free location that is adjacent to the
186	     * given location. If there is none, return null.
187	     * The returned location will be within the valid bounds
188	     * of the field.
189	     * @param location The location from which to generate an adjacency.
190	     * @return A valid location within the grid area.
191	     */
192	    public Location freeAdjacentLocation(Location location)
193	    {
194	        // The available free ones.
195	        List<Location> free = getFreeAdjacentLocations(location);
196	        if(free.size() > 0) {
197	            return free.get(0);
198	        }
199	        else {
200	            return null;
201	        }
202	    }
203	
204	    /**
205	     * Returns adjacent locations in the field containing a certain class
206	     * For example, adjacentSpecies(location, Grass.class) returns the adjacent locations with Grass
207	     * @param location The location of an organism.
208	     * @param speciesClass The type of species.
209	     * @return adjacentSpecies A list of adjacent locations with the specified species 
210	     */
211	    public List<Location> adjacentLocationsWithSpecies(Location location, Class<?> speciesClass) {
212	        List<Location> free = adjacentLocations(location);
213	        List<Location> res = new ArrayList<>();
214	        for (Location loc : free) {
215	            if (getObjectAt(loc) != null && getObjectAt(loc).getClass()==speciesClass) {
216	                res.add(loc);
217	            }
218	        }
219	        return res;
220	    }
221	
222	    /**
223	     * Return a shuffled list of locations adjacent to the given one.
224	     * The list will not include the location itself.
225	     * All locations will lie within the grid.
226	     * @param location The location from which to generate adjacencies.
227	     * @return A list of locations adjacent to that given.
228	     */
229	    public List<Location> adjacentLocations(Location location)
230	    {
231	        assert location != null : "Null location passed to adjacentLocations";
232	        // The list of locations to be returned.
233	        List<Location> locations = new LinkedList<>();
234	        if(location != null) {
235	            int row = location.getRow();
236	            int col = location.getCol();
237	            for(int roffset = -1; roffset <= 1; roffset++) {
238	                int nextRow = row + roffset;
239	                if(nextRow >= 0 && nextRow < depth) {
240	                    for(int coffset = -1; coffset <= 1; coffset++) {
241	                        int nextCol = col + coffset;
242	                        // Exclude invalid locations and the original location.
243	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) {
244	                            locations.add(new Location(nextRow, nextCol));
245	                        }
246	                    }
247	                }
248	            }
249	            
250	            // Shuffle the list. Several other methods rely on the list
251	            // being in a random order.
252	            Collections.shuffle(locations, rand);
253	        }
254	        return locations;
255	    }
256	
257	    /**
258	     * Return the depth of the field.
259	     * @return The depth of the field.
260	     */
261	    public int getDepth()
262	    {
263	        return depth;
264	    }
265	    
266	    /**
267	     * Return the width of the field.
268	     * @return The width of the field.
269	     */
270	    public int getWidth()
271	    {
272	        return width;
273	    }
274	}
