3	/**
4	 * This class models grass.
5	 * Grass can germinate, grow and get eaten by animals.
6	 *
7	 * @version 2022.03.02
8	 */
9	public class Grass extends Plant
10	{
11	    private static final PlantStats STATS = new PlantStats(3, 2);
12	
13	    @Override
14	    protected PlantStats getStats() { return STATS; }
15	
16	    private int foodValue;
17	    private static double GERMINATION_RATE = 0.1;
18	
19	    @Override
20	    protected int FOOD_VALUE() { return foodValue; }
21	
22	    /**
23	     * Creates grass with a random stage of growth.
24	     * Food value starts equal to the initial growth stage.
25	     *
26	     * @param field The field currently occupied.
27	     * @param location The location within the field.
28	     */
29	    public Grass(Field field, Location location)
30	    {
31	        super(field, location);
32	        this.foodValue = getStageOfGrowth();
33	    }
34	
35	    /**
36	     * Make the grass act.
37	     * The germination rate is affected by weather; growth advances every stepsPerStage steps.
38	     * @param newGrass To store the newly germinated grass.
39	     * @param environment The environment that the grass resides in.
40	     */
41	    public void act(List<Actor> newGrass, Environment environment)
42	    {
43	        if (environment.getWeather().getCurrentWeather() == WeatherType.SUNNY) {
44	            changeGerminationRate(0.15);
45	        } else {
46	            changeGerminationRate(0.1);
47	        }
48	
49	        if (environment.getTime().getStep() % getStats().getStepsPerStage() == 0) {
50	            incrementGrowth();
51	        }
52	
53	        if (isAlive() && environment.getTime().isDay() && rand.nextDouble() <= GERMINATION_RATE
54	                && environment.getWeather().getCurrentWeather() != WeatherType.CLOUDY) {
55	            germinate(newGrass);
56	        }
57	    }
58	
59	    /**
60	     * Spread to all free adjacent locations.
61	     * @param newGrass A list to return newly created grass.
62	     */
63	    protected void germinate(List<Actor> newGrass)
64	    {
65	        Field field = getField();
66	        for (Location loc : field.getFreeAdjacentLocations(getLocation())) {
67	            newGrass.add(new Grass(field, loc));
68	        }
69	    }
70	
71	    /**
72	     * Change the germination rate of grass.
73	     * @param newRate The new germination rate.
74	     */
75	    public void changeGerminationRate(double newRate)
76	    {
77	        if (isAlive()) {
78	            GERMINATION_RATE = newRate;
79	        }
80	    }
81	
82	    /**
83	     * Advance the growth stage and increase food value accordingly.
84	     * @return true if the grass grew; false if already at maximum stage.
85	     */
86	    @Override
87	    public boolean incrementGrowth()
88	    {
89	        if (super.incrementGrowth()) {
90	            foodValue++;
91	            return true;
92	        }
93	        return false;
94	    }
95	}
