2	
3	/**
4	 * A simple model of a hunter.
5	 * Hunters hunt all animal species in the simulation.
6	 *
7	 * @version 2022.03.02
8	 */
9	public class Hunter extends Organism implements Actor
10	{
11	    private static final Random rand = Randomizer.getRandom();
12	
13	    // Hunters cannot be eaten, so they contribute no food value.
14	    @Override
15	    protected int FOOD_VALUE() { return 0; }
16	
17	    // A hunter preys on every animal species.
18	    private static final Set<Class> DIET = Set.of(
19	        Deer.class, Mouse.class, Wolf.class, Coyote.class, Eagle.class
20	    );
21	
22	    /**
23	     * Creates a new hunter at the given location.
24	     * @param field The field currently occupied.
25	     * @param location The location within the field.
26	     */
27	    public Hunter(Field field, Location location)
28	    {
29	        super(field, location);
30	    }
31	
32	    /**
33	     * Makes the hunter hunt for nearby animals.
34	     * @param newActors A list to receive new actors (unused — hunters do not reproduce).
35	     * @param environment The environment that the hunter resides in.
36	     */
37	    public void act(List<Actor> newActors, Environment environment)
38	    {
39	        if (isAlive()) {
40	            Location newLocation = findPrey();
41	            if (newLocation == null) {
42	                newLocation = getField().freeAdjacentLocation(getLocation());
43	            }
44	            List<Location> adjacentGrassSpots = getField().adjacentLocationsWithSpecies(getLocation(), Grass.class);
45	
46	            if (newLocation != null) {
47	                setLocation(newLocation);
48	            } else if (adjacentGrassSpots.size() > 0) {
49	                getField().clear(getLocation());
50	                setLocation(adjacentGrassSpots.get(rand.nextInt(adjacentGrassSpots.size())));
51	            }
52	        }
53	    }
54	
55	    /**
56	     * Look for animals adjacent to the current location.
57	     * Only the first live animal found is killed.
58	     * @return The location where an animal was found, or null if none.
59	     */
60	    private Location findPrey()
61	    {
62	        for (Location where : getField().adjacentLocations(getLocation())) {
63	            Object obj = getField().getObjectAt(where);
64	            if (obj != null && DIET.contains(obj.getClass())) {
65	                Animal prey = (Animal) obj;
66	                if (prey.isAlive()) {
67	                    prey.setDead();
68	                }
69	                return where;
70	            }
71	        }
72	        return null;
73	    }
74	}
