10	 * @version 2022.03.02
11	 */
12	public class SimulationEngine implements SimulationControls
13	{
14	    static final int DEFAULT_DEPTH = 160;
15	    static final int DEFAULT_WIDTH = 240;
16	
17	    private static final int HUNTER_LIMIT = 5;
18	    private static final Random rand = Randomizer.getRandom();
19	
20	    private static final Map<Class<?>, Double> DEFAULT_PROBABILITIES = Map.ofEntries(
21	            Map.entry(Coyote.class, 0.010),
22	            Map.entry(Deer.class,   0.080),
23	            Map.entry(Wolf.class,   0.010),
24	            Map.entry(Eagle.class,  0.010),
25	            Map.entry(Mouse.class,  0.080),
26	            Map.entry(Grass.class,  0.030),
27	            Map.entry(Hunter.class, 0.030)
28	    );
29	
30	    private boolean playingSimulation = false;
31	    private int remainingSteps;
32	    private int hunterCount = 0;
33	
34	    private final Map<Class<?>, Double> creationProbabilities;
35	    private final SimulationObserver observer;
36	
37	    private List<Actor> actors;
38	    private Field field;
39	    private int step;
40	    private Environment environment;
41	
42	    /**
43	     * Create an engine with default creation probabilities.
44	     * @param depth    Depth of the simulation field.
45	     * @param width    Width of the simulation field.
46	     * @param observer Observer that receives step notifications and answers viability queries.
47	     */
48	    public SimulationEngine(int depth, int width, SimulationObserver observer)
49	    {
50	        this(depth, width, DEFAULT_PROBABILITIES, observer);
51	    }
52	
53	    /**
54	     * Create an engine with custom creation probabilities.
55	     * @param depth                Depth of the simulation field.
56	     * @param width                Width of the simulation field.
57	     * @param creationProbabilities Per-class spawn probability used during populate().
58	     * @param observer             Observer that receives step notifications and answers viability queries.
59	     */
60	    public SimulationEngine(int depth, int width, Map<Class<?>, Double> creationProbabilities,
61	                            SimulationObserver observer)
62	    {
63	        this.creationProbabilities = creationProbabilities;
64	        this.observer = observer;
65	        actors = new ArrayList<>();
66	        field = new Field(depth, width);
67	        environment = new Environment(new Time(), new Weather());
68	    }
69	
70	    // --- SimulationControls implementation ---
71	
72	    @Override
73	    public void stepOnce()
74	    {
75	        if (!playingSimulation) {
76	            playingSimulation = true;
77	            simulateOneStep();
78	            playingSimulation = false;
79	        }
80	    }
81	
82	    @Override
83	    public void runLongSimulation()
84	    {
85	        remainingSteps += 4000;
86	        simulate(remainingSteps);
87	    }
88	
89	    @Override
90	    public void stop()
91	    {
92	        playingSimulation = false;
93	    }
94	
95	    @Override
96	    public void reset()
97	    {
98	        step = 0;
99	        hunterCount = 0;
100	        actors.clear();
101	        populate();
102	        environment.getTime().reset();
103	        observer.onStep(step, environment, field);
104	    }
105	
106	    @Override
107	    public boolean isPlaying()
108	    {
109	        return playingSimulation;
110	    }
111	
112	    // --- Simulation loop ---
113	
114	    /**
115	     * Run the simulation from its current state for the given number of steps.
116	     * Stops early if the population ceases to be viable.
117	     */
118	    public void simulate(int numSteps)
119	    {
120	        playingSimulation = true;
121	        remainingSteps = numSteps;
122	
123	        int stepsDone = 1;
124	        while (playingSimulation) {
125	            for (int s = 1; s <= numSteps && observer.isViable(field); s++) {
126	                simulateOneStep();
127	                stepsDone++;
128	            }
129	            if (!observer.isViable(field)) {
130	                if (stepsDone > SimulationInfo.HIGHEST_STEPS) {
131	                    SimulationInfo.HIGHEST_STEPS = stepsDone;
132	                    SimulationInfo.HIGHEST_STEP_PROBS = this.creationProbabilities;
133	                }
134	                playingSimulation = false;
135	                break;
136	            }
137	        }
138	        remainingSteps = numSteps - stepsDone;
139	    }
140	
141	    /**
142	     * Run the simulation from its current state for a single step.
143	     * Iterates over the whole field, letting each actor act.
144	     */
145	    public void simulateOneStep()
146	    {
147	        if (!playingSimulation) { return; }
148	        step++;
149	        environment.getTime().incrementTime();
150	        environment.getWeather().checkWeatherChange(step);
151	
152	        List<Actor> newActors = new ArrayList<>();
153	        for (Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
154	            Actor actor = it.next();
155	            actor.act(newActors, environment);
156	            if (!actor.isAlive()) {
157	                it.remove();
158	            }
159	        }
160	        actors.addAll(newActors);
161	        plantGrassInPatches();
162	
163	        observer.onStep(step, environment, field);
164	    }
165	
166	    // --- Field management ---
167	
168	    /**
169	     * Randomly generate grass in free patches on the field, only if it is raining.
170	     */
171	    private void plantGrassInPatches()
172	    {
173	        for (Location location : field.getRandomFreePatches(creationProbabilities.get(Grass.class))) {
174	            if (rand.nextDouble() <= creationProbabilities.get(Grass.class)
175	                    && environment.getWeather().getCurrentWeather() == WeatherType.RAINING) {
176	                actors.add(new Grass(field, location));
177	            }
178	        }
179	    }
180	
181	    /**
182	     * Randomly populate the field with organisms.
183	     * The factory map determines which actor is spawned at each cell; entries
184	     * are tried in insertion order and only the first match is placed per cell.
185	     */
186	    private void populate()
187	    {
188	        LinkedHashMap<Class<?>, BiFunction<Location, Gender, Actor>> factories = new LinkedHashMap<>();
189	        factories.put(Grass.class,  (loc, sex) -> new Grass(field, loc));
190	        factories.put(Deer.class,   (loc, sex) -> new Deer(true, field, loc, sex));
191	        factories.put(Coyote.class, (loc, sex) -> new Coyote(true, field, loc, sex));
192	        factories.put(Wolf.class,   (loc, sex) -> new Wolf(true, field, loc, sex));
193	        factories.put(Eagle.class,  (loc, sex) -> new Eagle(true, field, loc, sex));
194	        factories.put(Mouse.class,  (loc, sex) -> new Mouse(true, field, loc, sex));
195	        factories.put(Hunter.class, (loc, sex) -> new Hunter(field, loc));
196	
197	        field.clear();
198	        for (int row = 0; row < field.getDepth(); row++) {
199	            for (int col = 0; col < field.getWidth(); col++) {
200	                Location location = new Location(row, col);
201	                Gender sex = Randomizer.getRandomSex();
202	                for (Map.Entry<Class<?>, BiFunction<Location, Gender, Actor>> entry : factories.entrySet()) {
203	                    Class<?> cls = entry.getKey();
204	                    if (cls == Hunter.class && hunterCount >= HUNTER_LIMIT) continue;
205	                    if (rand.nextDouble() <= creationProbabilities.get(cls)) {
206	                        actors.add(entry.getValue().apply(location, sex));
207	                        if (cls == Hunter.class) hunterCount++;
208	                        break;
209	                    }
210	                }
211	                // else leave the location empty
212	            }
213	        }
214	    }
215	}
