3	/**
4	 * Thin entry-point that wires a {@link SimulationEngine} to a {@link SimulatorView}.
5	 * All simulation logic lives in SimulationEngine; this class is responsible only
6	 * for constructing the two collaborators and connecting them.
7	 *
8	 * @version 2022.03.02
9	 */
10	public class Simulator implements SimulationControls
11	{
12	    private final SimulationEngine engine;
13	
14	    /** Construct a simulation with default field size and default creation probabilities. */
15	    public Simulator()
16	    {
17	        this(SimulationEngine.DEFAULT_DEPTH, SimulationEngine.DEFAULT_WIDTH);
18	    }
19	
20	    /**
21	     * Construct a simulation with a custom field size and default creation probabilities.
22	     * @param depth Depth of the field. Must be greater than zero.
23	     * @param width Width of the field. Must be greater than zero.
24	     */
25	    public Simulator(int depth, int width)
26	    {
27	        if (width <= 0 || depth <= 0) {
28	            System.out.println("The dimensions must be greater than zero.");
29	            System.out.println("Using default values.");
30	            depth = SimulationEngine.DEFAULT_DEPTH;
31	            width = SimulationEngine.DEFAULT_WIDTH;
32	        }
33	        SimulatorView view = buildView(depth, width);
34	        engine = new SimulationEngine(depth, width, view);
35	        view.wireButtons(this);
36	        engine.reset();
37	    }
38	
39	    /**
40	     * Construct a simulation with custom creation probabilities.
41	     * Useful for testing different probability combinations to find an optimal configuration.
42	     */
43	    public Simulator(double GrassProbability, double DeerProbability, double CoyoteProbability,
44	                     double WolfProbability, double EagleProbability, double HunterProbability,
45	                     double MouseProbability)
46	    {
47	        SimulatorView view = buildView(SimulationEngine.DEFAULT_DEPTH, SimulationEngine.DEFAULT_WIDTH);
48	        Map<Class<?>, Double> probs = Map.ofEntries(
49	                Map.entry(Coyote.class, CoyoteProbability),
50	                Map.entry(Deer.class,   DeerProbability),
51	                Map.entry(Wolf.class,   WolfProbability),
52	                Map.entry(Eagle.class,  EagleProbability),
53	                Map.entry(Mouse.class,  MouseProbability),
54	                Map.entry(Grass.class,  GrassProbability),
55	                Map.entry(Hunter.class, HunterProbability)
56	        );
57	        engine = new SimulationEngine(SimulationEngine.DEFAULT_DEPTH, SimulationEngine.DEFAULT_WIDTH, probs, view);
58	        view.wireButtons(this);
59	        engine.reset();
60	    }
61	
62	    // --- SimulationControls delegation ---
63	
64	    @Override public void stepOnce()          { engine.stepOnce(); }
65	    @Override public void runLongSimulation() { engine.runLongSimulation(); }
66	    @Override public void stop()              { engine.stop(); }
67	    @Override public void reset()             { engine.reset(); }
68	    @Override public boolean isPlaying()      { return engine.isPlaying(); }
69	
70	    /** Delegates to the engine for callers that need direct step control (e.g. TestingMain). */
71	    public void simulate(int numSteps)        { engine.simulate(numSteps); }
72	    public void simulateOneStep()             { engine.simulateOneStep(); }
73	
74	    // --- View construction ---
75	
76	    private static SimulatorView buildView(int depth, int width)
77	    {
78	        SimulatorView view = new SimulatorView(depth, width);
79	        for (Class cls : SimulationInfo.DEFAULT_COLOR_MAP.keySet()) {
80	            view.setColor(cls, SimulationInfo.DEFAULT_COLOR_MAP.get(cls));
81	        }
82	        return view;
83	    }
84	}
