307	    /**
308	     * Provide a graphical view of a rectangular field. This is
309	     * a nested class (a class defined inside a class) which
310	     * defines a custom component for the user interface. This
311	     * component displays the field.
312	     * This is rather advanced GUI stuff - you can ignore This
313	     * for your project if you like.
314	     */
315	    private class FieldView extends JPanel
316	    {
317	        private final int GRID_VIEW_SCALING_FACTOR = 4;
318	
319	        private int gridWidth, gridHeight;
320	        private int xScale, yScale;
321	        Dimension size;
322	        private Graphics g;
323	        private Image fieldImage;
324	
325	        /**
326	         * Create a new FieldView component.
327	         */
328	        public FieldView(int height, int width)
329	        {
330	            gridHeight = height;
331	            gridWidth = width;
332	            size = new Dimension(0, 0);
333	        }
334	
335	        /**
336	         * Tell the GUI manager how big we would like to be.
337	         */
338	        public Dimension getPreferredSize()
339	        {
340	            return new Dimension(gridWidth * GRID_VIEW_SCALING_FACTOR,
341	                                 gridHeight * GRID_VIEW_SCALING_FACTOR);
342	        }
343	
344	        /**
345	         * Prepare for a new round of painting. Since the component
346	         * may be resized, compute the scaling factor again.
347	         */
348	        public void preparePaint()
349	        {
350	            if(! size.equals(getSize())) {  // if the size has changed...
351	                size = getSize();
352	                fieldImage = fieldView.createImage(size.width, size.height);
353	                g = fieldImage.getGraphics();
354	
355	                xScale = size.width / gridWidth;
356	                if(xScale < 1) {
357	                    xScale = GRID_VIEW_SCALING_FACTOR;
358	                }
359	                yScale = size.height / gridHeight;
360	                if(yScale < 1) {
361	                    yScale = GRID_VIEW_SCALING_FACTOR;
362	                }
363	            }
364	        }
365	
366	        /**
367	         * Paint on grid location on the field in a given color.
368	         */
369	        public void drawMark(int x, int y, Color color)
370	        {
371	            g.setColor(color);
