1	/**
2	 * This class models time in the simulation. 
3	 * It stores details about time such as whether it is day or night,
4	 * the number of days the simulation has simulated through 
5	 * and the current time.
6	 *
7	 * @version 2022.03.2
8	*/
9	public class Time 
10	{
11	    // to keep track of the flow of time
12	    private int stepCount;
13	    private int dayCount;
14	    private TimesOfDay dayOrNight;
15	    
16	    
17	    /**
18	     * Create a new instance of time with the step set to 0.
19	     */
20	    public Time() 
21	    {
22	        stepCount = 0;
23	        dayOrNight = TimesOfDay.NIGHT;
24	    }
25	
26	    /**
27	     * Increments the time by 1. 
28	     * Additionally increments the day counter if
29	     * 24 hours have passed. 
30	     * Calls the method checkDayOrNight()
31	     */
32	    public void incrementTime()
33	    {
34	        stepCount++;
35	        if(stepCount % 24 == 0){
36	            dayCount++;
37	        }
38	        checkDayOrNight();
39	    }
40	
41	    /**
42	     * Checks the current hour and then sets 
43	     * time as day or night accordingly. 
44	     */
45	    public void checkDayOrNight()
46	    {
47	        if (getHour() >= 6 && getHour() <= 19) {
48	            dayOrNight = TimesOfDay.DAY;
49	        }
50	        else {
51	            dayOrNight  = TimesOfDay.NIGHT;
52	        }
53	    }
54	
55	    /**
56	     * Returns the current hour of the simulation. 
57	     */
58	    private int getHour() 
59	    {
60	        return stepCount % 24; 
61	    }
62	
63	    /**
64	     * Returns the current hour of the simulation 
65	     * as a string.
66	     */
67	    private String getHourString() 
68	    {
69	        int hour = getHour();
70	        if(hour < 10){
71	            return "0"+hour+":00";
72	        }
73	        return ""+hour+":00";
74	    }
75	
76	    /**
77	     * Returns true if it is currently day time.
78	     */
79	    public boolean isDay() 
80	    {
81	        return dayOrNight==TimesOfDay.DAY;
82	    }
83	
84	    /**
85	     * Returns the current time of the day.
86	     * Whether it is daytime or nighttime. 
87	     */
88	    public TimesOfDay getCurrentPeriod()
89	    {
90	        return dayOrNight;
91	    }
92	
93	    /**
94	     * Returns the current time as a string.
95	     */
96	    public String getCurrentTimeString()
97	    {
98	        return " (" + getCurrentPeriod().toString() + ")" + " Day #" + dayCount + " " + getHourString();
99	    }
100	
101	    /**
102	     * Returns the current simulation step count.
103	     */
104	    public int getStep()
105	    {
106	        return stepCount;
107	    }
108	
109	    /**
110	     * Returns the day count number.
111	     */
112	    private int getDayCount()
113	    {
114	        return dayCount;
115	    }
116	
117	    /**
118	     * Reset the time object
119	     */
120	    public void reset(){
121	        stepCount = 0;
122	        dayCount = 0;
123	        dayOrNight = TimesOfDay.NIGHT;
124	    }
125	}
