3	/**
4	 * This class models weather in the simulation. 
5	 * It stores information about the current weather. 
6	 *
7	 * @version 2022.03.02
8	 */
9	public class Weather
10	{
11	    private WeatherType currentWeather;
12	    private static final Random rand = Randomizer.getRandom();
13	    private int randomInt;
14	    private int duration; // to keep track of when weather changes (every X hours)
15	    private boolean randomDuration = false;
16	    private Set<WeatherType> weatherList;
17	    
18	    
19	    /**
20	     * Create a new instance of weather. 
21	     */
22	    public Weather()
23	    {
24	       weatherList = new HashSet<>();
25	       addWeatherList();
26	       currentWeather = WeatherType.SUNNY; 
27	       duration = 0;
28	    }
29	
30	    /**
31	     * Add the types of weather conditions to a HashSet.
32	     */
33	    public void addWeatherList()
34	    {
35	        weatherList = new HashSet<>(Arrays.asList(WeatherType.RAINING, WeatherType.SUNNY, WeatherType.CLOUDY));
36	    }
37	    
38	    /**
39	     * Returns the current weather of the simulation. 
40	     */
41	    public WeatherType getCurrentWeather()
42	    {
43	        return currentWeather;
44	    }
45	    
46	    /**
47	     * Increments the variable duration. 
48	     * If the duration is set to be random, the WeatherType lasts for 0-36 hours
49	     * Otherwise, the WeatherType lasts for 12 hours
50	     */
51	    public void checkWeatherChange(int steps)
52	    {
53	        if(randomDuration){
54	            duration = rand.nextInt(36);
55	            if(steps % duration==0){
56	                changeWeather();
57	            }
58	        }
59	        else{
60	            if (steps % 12 == 0){
61	                changeWeather();
62	            }
63	        }
64	    }
65	
66	    /**
67	     * Allows for the duration of the weather to be switched from random (0-36 steps) to static (12 steps)
68	     * @return The new state of the randomDuration boolean
69	     */
70	    public boolean toggleRandomWeatherLength()
71	    {
72	        randomDuration = !randomDuration;
73	        return randomDuration;
74	    }
75	    
76	    /**
77	     * Changes the weather randomly. 
78	     */
79	    public void changeWeather()
80	    {
81	        randomInt = rand.nextInt(weatherList.size());
82	        currentWeather = (WeatherType) weatherList.toArray()[randomInt];
83	    }
84	}
